import{_ as a,o,c as s,ae as t}from"./chunks/framework.Bwt6MOeu.js";const u=JSON.parse('{"title":"SocioProphet Repository Documentation (Pedantic)","description":"","frontmatter":{},"headers":[],"relativePath":"pedantic-documentation.md","filePath":"pedantic-documentation.md"}'),n={name:"pedantic-documentation.md"};function i(r,e,l,c,d,p){return o(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="socioprophet-repository-documentation-pedantic" tabindex="-1">SocioProphet Repository Documentation (Pedantic) <a class="header-anchor" href="#socioprophet-repository-documentation-pedantic" aria-label="Permalink to &quot;SocioProphet Repository Documentation (Pedantic)&quot;">​</a></h1><h2 id="_0-purpose-and-scope" tabindex="-1">0. Purpose and Scope <a class="header-anchor" href="#_0-purpose-and-scope" aria-label="Permalink to &quot;0. Purpose and Scope&quot;">​</a></h2><p>This repository contains the source code and tooling for the SocioProphet web application. The codebase is split into a browser client (React/TypeScript) and a server (Node/Express) that currently proxies and caches a Hacker News RSS feed for the website’s scrolling ticker. This document is intentionally exhaustive: it describes <em>what exists</em>, <em>why it exists</em>, and <em>how the pieces fit together</em>.</p><blockquote><p><strong>What this is not:</strong> This repository does not currently contain any API definitions or business logic beyond the RSS feed proxying/ticker support. Any references to “TriTRPC” or other systems are not present in this codebase.</p></blockquote><h2 id="_1-repository-layout" tabindex="-1">1. Repository Layout <a class="header-anchor" href="#_1-repository-layout" aria-label="Permalink to &quot;1. Repository Layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.</span></span>
<span class="line"><span>├── CONTRIBUTING.md</span></span>
<span class="line"><span>├── Makefile</span></span>
<span class="line"><span>├── README.md</span></span>
<span class="line"><span>├── docs/</span></span>
<span class="line"><span>│   └── pedantic-documentation.md</span></span>
<span class="line"><span>└── socioprophet-web/</span></span>
<span class="line"><span>    ├── client/                 # React 18 + TypeScript UI</span></span>
<span class="line"><span>    ├── server/                 # Express server serving RSS data</span></span>
<span class="line"><span>    └── scripts/                # Shell helpers used by the Makefile</span></span></code></pre></div><h3 id="_1-1-root-files" tabindex="-1">1.1 Root Files <a class="header-anchor" href="#_1-1-root-files" aria-label="Permalink to &quot;1.1 Root Files&quot;">​</a></h3><ul><li><strong>README.md</strong>: quickstart, high-level description, and make targets.</li><li><strong>CONTRIBUTING.md</strong>: contribution guidance.</li><li><strong>Makefile</strong>: convenience targets for installing dependencies and running the app.</li></ul><h3 id="_1-2-socioprophet-web-subtree" tabindex="-1">1.2 <code>socioprophet-web/</code> Subtree <a class="header-anchor" href="#_1-2-socioprophet-web-subtree" aria-label="Permalink to &quot;1.2 \`socioprophet-web/\` Subtree&quot;">​</a></h3><ul><li><strong>client/</strong>: React 18 app using TypeScript, Webpack, and Styled Components.</li><li><strong>server/</strong>: Express server that fetches and caches the Hacker News RSS feed.</li><li><strong>scripts/</strong>: shell scripts invoked by the Makefile.</li></ul><h2 id="_2-theory-and-design-rationale" tabindex="-1">2. Theory and Design Rationale <a class="header-anchor" href="#_2-theory-and-design-rationale" aria-label="Permalink to &quot;2. Theory and Design Rationale&quot;">​</a></h2><p>This project uses a classic <strong>client/server split</strong>. The theory behind this choice is to separate concerns:</p><ol><li><p><strong>Separation of responsibilities</strong></p><ul><li>The <strong>client</strong> focuses exclusively on presentation and user experience.</li><li>The <strong>server</strong> centralizes integration with external data sources (Hacker News RSS), providing a stable API for the client.</li></ul></li><li><p><strong>Reduced browser responsibilities</strong></p><ul><li>Browsers are limited in cross-origin requests and can be blocked by CORS. By routing external data fetches through an Express server, you minimize CORS and security complexity for the client.</li></ul></li><li><p><strong>Cache locality and performance</strong></p><ul><li>The server caches RSS responses with a TTL. This prevents repeated hits to the external RSS endpoint and stabilizes the data rate consumed by clients. Caching is done in-process to keep latency and configuration overhead low.</li></ul></li><li><p><strong>Security and operational hygiene</strong></p><ul><li>Middleware like <code>helmet</code>, <code>compression</code>, <code>cookie-parser</code>, and <code>cors</code> provide a baseline security and performance posture. The theory is to <strong>opt into default hardening</strong> rather than needing to add protections ad hoc later.</li></ul></li></ol><p>In short: <em>theory = isolate external data access and caching in a minimal server layer, while keeping the client UI focused and responsive.</em></p><h2 id="_3-client-application-socioprophet-web-client" tabindex="-1">3. Client Application (<code>socioprophet-web/client/</code>) <a class="header-anchor" href="#_3-client-application-socioprophet-web-client" aria-label="Permalink to &quot;3. Client Application (\`socioprophet-web/client/\`)&quot;">​</a></h2><h3 id="_3-1-entry-points" tabindex="-1">3.1 Entry Points <a class="header-anchor" href="#_3-1-entry-points" aria-label="Permalink to &quot;3.1 Entry Points&quot;">​</a></h3><ul><li><strong><code>src/index.tsx</code></strong>: React entry point that mounts the app to the DOM.</li><li><strong><code>src/App.tsx</code></strong>: top-level application component.</li></ul><h3 id="_3-2-ui-organization" tabindex="-1">3.2 UI Organization <a class="header-anchor" href="#_3-2-ui-organization" aria-label="Permalink to &quot;3.2 UI Organization&quot;">​</a></h3><ul><li><strong><code>src/components/</code></strong>: reusable UI components.</li><li><strong><code>src/views/</code></strong>: higher-level screens or routes.</li><li><strong><code>src/globalStyles.tsx</code></strong>: global styling (Styled Components).</li><li><strong><code>src/constants/</code></strong>: client-side constants.</li></ul><h3 id="_3-3-routing" tabindex="-1">3.3 Routing <a class="header-anchor" href="#_3-3-routing" aria-label="Permalink to &quot;3.3 Routing&quot;">​</a></h3><ul><li><strong><code>src/routes.js</code></strong> and <strong><code>src/routes.d.ts</code></strong> define route configuration and typings.</li></ul><h3 id="_3-4-theory-ui-layering" tabindex="-1">3.4 Theory: UI Layering <a class="header-anchor" href="#_3-4-theory-ui-layering" aria-label="Permalink to &quot;3.4 Theory: UI Layering&quot;">​</a></h3><p>The UI is layered with a “components” and “views” split. This aligns with a common UI architecture where:</p><ul><li><strong>Components</strong> are reusable, low-level building blocks.</li><li><strong>Views</strong> are compositional containers that bind data to components.</li></ul><p>This reduces coupling and keeps stateful orchestration (e.g., data fetching, view-specific layout) out of reusable UI primitives.</p><h2 id="_4-server-application-socioprophet-web-server" tabindex="-1">4. Server Application (<code>socioprophet-web/server/</code>) <a class="header-anchor" href="#_4-server-application-socioprophet-web-server" aria-label="Permalink to &quot;4. Server Application (\`socioprophet-web/server/\`)&quot;">​</a></h2><h3 id="_4-1-entry-point" tabindex="-1">4.1 Entry Point <a class="header-anchor" href="#_4-1-entry-point" aria-label="Permalink to &quot;4.1 Entry Point&quot;">​</a></h3><ul><li><strong><code>src/server.ts</code></strong>: configures middleware and registers routes.</li></ul><p>Key middleware used:</p><ul><li><code>cookie-session</code>: simple session support for future stateful interactions.</li><li><code>cors</code>: cross-origin request support for the client.</li><li><code>helmet</code>: secure HTTP headers.</li><li><code>compression</code>: gzip responses to reduce payload size.</li><li><code>express.json</code> / <code>express.urlencoded</code>: request parsing.</li><li><code>cookie-parser</code>: cookie parsing.</li></ul><h3 id="_4-2-rss-feed-route" tabindex="-1">4.2 RSS Feed Route <a class="header-anchor" href="#_4-2-rss-feed-route" aria-label="Permalink to &quot;4.2 RSS Feed Route&quot;">​</a></h3><ul><li><strong><code>src/routes/api/rss-route.ts</code></strong>: fetches and caches the Hacker News RSS feed.</li></ul><p>Request path:</p><ul><li><code>GET /api/feed/rss</code></li></ul><p>Behavior:</p><ol><li>Check in-memory cache (node-cache) for <code>HN_URL</code>.</li><li>If cached, return cached items.</li><li>If not cached, fetch RSS feed, parse XML via <code>jsdom</code>, extract <code>&lt;item&gt;</code> nodes, and cache results.</li></ol><h3 id="_4-3-theory-simple-server-side-cache" tabindex="-1">4.3 Theory: Simple Server-Side Cache <a class="header-anchor" href="#_4-3-theory-simple-server-side-cache" aria-label="Permalink to &quot;4.3 Theory: Simple Server-Side Cache&quot;">​</a></h3><p>The server uses a memory cache with a TTL to balance:</p><ul><li><strong>Freshness</strong>: The TTL ensures data is updated regularly.</li><li><strong>Rate limiting</strong>: Reduces the frequency of external requests.</li><li><strong>Latency</strong>: Allows instant response for repeated client requests within the TTL window.</li></ul><p>This cache strategy is intentionally simple because the data is read-only and small; a full external cache (Redis) would add operational overhead without clear benefit.</p><h2 id="_5-configuration-environment-variables" tabindex="-1">5. Configuration &amp; Environment Variables <a class="header-anchor" href="#_5-configuration-environment-variables" aria-label="Permalink to &quot;5. Configuration &amp; Environment Variables&quot;">​</a></h2><p>The server loads environment variables from <code>.env</code> in non-production environments (<code>dotenv</code>).</p><h3 id="_5-1-expected-files" tabindex="-1">5.1 Expected Files <a class="header-anchor" href="#_5-1-expected-files" aria-label="Permalink to &quot;5.1 Expected Files&quot;">​</a></h3><ul><li><strong><code>socioprophet-web/client/.env</code></strong> (see <code>.env.example</code> for client variables)</li><li><strong><code>socioprophet-web/server/.env</code></strong> (see <code>.env.examples</code> for server variables)</li></ul><h3 id="_5-2-theory-environment-separation" tabindex="-1">5.2 Theory: Environment Separation <a class="header-anchor" href="#_5-2-theory-environment-separation" aria-label="Permalink to &quot;5.2 Theory: Environment Separation&quot;">​</a></h3><p>Keeping environment values in <code>.env</code> files prevents hardcoding secrets into the repository and makes it easy to switch between local/dev/prod contexts.</p><h2 id="_6-build-install-and-run" tabindex="-1">6. Build, Install, and Run <a class="header-anchor" href="#_6-build-install-and-run" aria-label="Permalink to &quot;6. Build, Install, and Run&quot;">​</a></h2><h3 id="_6-1-make-targets" tabindex="-1">6.1 Make Targets <a class="header-anchor" href="#_6-1-make-targets" aria-label="Permalink to &quot;6.1 Make Targets&quot;">​</a></h3><p>The root <code>Makefile</code> provides two targets:</p><ul><li><code>make install_web</code> → runs <code>socioprophet-web/scripts/install_web.sh</code></li><li><code>make run_web</code> → runs <code>socioprophet-web/scripts/run_web.sh</code></li></ul><h3 id="_6-2-theory-make-as-a-thin-orchestration-layer" tabindex="-1">6.2 Theory: Make as a Thin Orchestration Layer <a class="header-anchor" href="#_6-2-theory-make-as-a-thin-orchestration-layer" aria-label="Permalink to &quot;6.2 Theory: Make as a Thin Orchestration Layer&quot;">​</a></h3><p>Make is used here as a lightweight command dispatcher. This keeps complexity out of developer workflows, allowing consistent local setup without requiring contributors to remember detailed commands.</p><h2 id="_7-data-flow-summary" tabindex="-1">7. Data Flow Summary <a class="header-anchor" href="#_7-data-flow-summary" aria-label="Permalink to &quot;7. Data Flow Summary&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser (React client)</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       |  GET /api/feed/rss</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>Express server (rss-route.ts)</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>       |  fetch HN_URL</span></span>
<span class="line"><span>       v</span></span>
<span class="line"><span>External RSS endpoint (Hacker News)</span></span></code></pre></div><p>Key points:</p><ul><li>Client never fetches the RSS URL directly.</li><li>Server caches and normalizes data into <code>{ title, link }</code> pairs.</li></ul><h2 id="_8-operational-notes" tabindex="-1">8. Operational Notes <a class="header-anchor" href="#_8-operational-notes" aria-label="Permalink to &quot;8. Operational Notes&quot;">​</a></h2><ul><li>The server listens on <code>process.env.PORT</code>; ensure it is set in the server <code>.env</code>.</li><li>The server handles <code>SIGINT</code> and closes the HTTP server for graceful shutdown.</li></ul><h2 id="_9-extension-points" tabindex="-1">9. Extension Points <a class="header-anchor" href="#_9-extension-points" aria-label="Permalink to &quot;9. Extension Points&quot;">​</a></h2><p>Possible future evolution paths, aligned with the existing structure:</p><ul><li>Replace in-memory cache with Redis if scaling becomes necessary.</li><li>Add server endpoints for additional data sources (e.g., other feeds).</li><li>Implement client-side error handling/loading states around RSS consumption.</li></ul><h2 id="_10-glossary" tabindex="-1">10. Glossary <a class="header-anchor" href="#_10-glossary" aria-label="Permalink to &quot;10. Glossary&quot;">​</a></h2><ul><li><strong>RSS</strong>: XML-based syndication format for updates.</li><li><strong>TTL</strong>: Time-to-live; duration before a cached entry is expired.</li><li><strong>CORS</strong>: Cross-Origin Resource Sharing; a browser security policy.</li></ul>`,63)])])}const g=a(n,[["render",i]]);export{u as __pageData,g as default};
